<?php
require __DIR__.'/../app/bootstrap.php'; admin_required();$pdo=db();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');if($id){if($action==='move'){$cat=(int)($_POST['category_id']??0);$check=$pdo->prepare('SELECT id FROM categories WHERE id=?');$check->execute([$cat]);if($check->fetchColumn())$pdo->prepare('UPDATE topics SET category_id=? WHERE id=?')->execute([$cat,$id]);}if($action==='hide')$pdo->prepare('UPDATE topics SET is_hidden=CASE is_hidden WHEN 1 THEN 0 ELSE 1 END WHERE id=?')->execute([$id]);if($action==='lock')$pdo->prepare('UPDATE topics SET is_locked=CASE is_locked WHEN 1 THEN 0 ELSE 1 END WHERE id=?')->execute([$id]);if($action==='pin')$pdo->prepare('UPDATE topics SET is_pinned=CASE is_pinned WHEN 1 THEN 0 ELSE 1 END WHERE id=?')->execute([$id]);$notice='Змінено.';}}
$topics=$pdo->query('SELECT t.*,c.title category_title,u.display_name,(SELECT COUNT(*) FROM posts p WHERE p.topic_id=t.id) replies FROM topics t JOIN categories c ON c.id=t.category_id LEFT JOIN users u ON u.id=t.user_id ORDER BY t.updated_at DESC')->fetchAll();forum_header('Теми — Admin');?><section class="page-title"><a href="/admin/">← Адмінка</a><h1>Теми</h1></section><?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif;?><div class="admin-table"><?php foreach($topics as $t):?><div class="admin-row topic-admin-row"><div><strong><?=e($t['title'])?></strong><span><?=e($t['category_title'])?> · <?=e($t['display_name']??'—')?> · <?=e((string)$t['replies'])?> відповідей</span><small><?=($t['is_hidden']?'прихована · ':'')?><?=($t['is_locked']?'закрита · ':'')?><?=($t['is_pinned']?'закріплена':'')?></small></div><div class="row-actions"><a class="btn" href="/topic.php?slug=<?=urlencode($t['slug'])?>">Відкрити</a><?php foreach([['hide',$t['is_hidden']?'Показати':'Приховати'],['lock',$t['is_locked']?'Відкрити':'Закрити'],['pin',$t['is_pinned']?'Відкріпити':'Закріпити']] as $a):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)$t['id'])?>"><input type="hidden" name="action" value="<?=$a[0]?>"><button class="btn"><?=$a[1]?></button></form><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><input type="hidden" name="action" value="move"><select name="category_id" aria-label="Нова категорія"><?php foreach($pdo->query('SELECT id,title FROM categories ORDER BY sort_order') as $c):?><option value="<?=(int)$c['id']?>" <?=$c['id']==$t['category_id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach;?></select><button class="btn">Перенести</button></form></div></div><?php endforeach;?></div><?php forum_footer(); ?>
